describe('proof', () => {
  it('resolves explicit !!float tags on integer and exponent-only forms under the JSON schema', () => {
    // YAML 1.2 JSON-schema float is -?(0|[1-9][0-9]*)(\.[0-9]*)?([eE][-+]?[0-9]+)?:
    // the fractional part is optional, so these must load instead of throwing.
    assert.strictEqual(load('!!float 5', { schema: JSON_SCHEMA }), 5);
    assert.strictEqual(load('!!float -2', { schema: JSON_SCHEMA }), -2);
    assert.strictEqual(load('!!float 1e3', { schema: JSON_SCHEMA }), 1000);
  });
});
"}, "note": "Removing the optional `?` from YAML_FLOAT_EXPLICIT_PATTERN makes the fraction mandatory for explicitly tagged floats in the JSON schema, so forms the pattern previously accepted (and which the YAML 1.2 JSON float regex allows), like `!!float 5` or `!!float 1e3`, now throw 'cannot resolve a node with !<tag:yaml.org,2002:float> explicit tag' instead of loading."}
